/**
 * AI 安全检查等级枚举
 */
export enum SafetyLevel {
  SAFE = 'SAFE',       // 可以安全食用
  CAUTION = 'CAUTION', // 需谨慎（如少量、去籽等）
  DANGEROUS = 'DANGEROUS', // 有毒或严重危害
  UNKNOWN = 'UNKNOWN'  // 无法判断
}

/**
 * AI 食物查询结果接口
 */
export interface FoodSafetyResult {
  foodName: string;
  petType: string;
  safetyLevel: SafetyLevel;
  explanation: string; // AI 提供的详细解释
  nutritionalValue?: string; // AI 提供的营养提示
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { PetType, SafetyLevel, FoodSafetyResult } from "../types";

// 从环境变量获取 API Key
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

/**
 * 定义 Gemini 响应的 JSON Schema
 * 确保 AI 返回的数据格式符合前端定义的接口
 */
const foodSafetySchema: Schema = {
  type: Type.OBJECT,
  properties: {
    safetyLevel: {
      type: Type.STRING,
      enum: [SafetyLevel.SAFE, SafetyLevel.CAUTION, SafetyLevel.DANGEROUS, SafetyLevel.UNKNOWN],
      description: "宠物食用该食物的安全等级",
    },
    explanation: {
      type: Type.STRING,
      description: "简洁的理由解释（中文）",
    },
    nutritionalValue: {
      type: Type.STRING,
      description: "补充的营养价值提示",
    },
  },
  required: ["safetyLevel", "explanation"],
};

/**
 * 调用 Gemini AI 检查食物安全性
 * @param foodName 食物名称
 * @param petType 宠物种类
 */
export const checkFoodSafety = async (foodName: string, petType: PetType): Promise<FoodSafetyResult> => {
  if (!apiKey) {
    return {
      foodName,
      petType,
      safetyLevel: SafetyLevel.UNKNOWN,
      explanation: "API Key 未配置，无法进行实时验证。",
    };
  }

  try {
    const prompt = `评估 ${petType} 是否可以吃 ${foodName}。请给出简洁的解释。语言要求：简体中文。`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: foodSafetySchema,
        systemInstruction: "你是一位资深的宠物兽医。在评估食物安全性时非常严谨。必须以 JSON 格式回复。",
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("AI 响应内容为空");

    const data = JSON.parse(jsonText);

    return {
      foodName,
      petType,
      safetyLevel: data.safetyLevel as SafetyLevel,
      explanation: data.explanation,
      nutritionalValue: data.nutritionalValue,
    };
  } catch (error) {
    console.error("Gemini API 调用失败:", error);
    return {
      foodName,
      petType,
      safetyLevel: SafetyLevel.UNKNOWN,
      explanation: "连接 AI 服务失败，请稍后重试。",
    };
  }
};

import React, { useState, useEffect } from 'react';
import { Pet, User, Post, Comment } from './types';
import { Navigation } from './components/Navigation';
import { PetManager } from './views/PetManager';
import { CareGuide } from './views/CareGuide';
import { FoodChecker } from './views/FoodChecker';
import { Auth } from './views/Auth';
import { Community } from './views/Community';

/**
 * App 核心管理组件
 * 负责全局状态维护（用户、宠物列表、帖子）以及数据本地持久化
 */
const App: React.FC = () => {
  // 核心状态
  const [currentUser, setCurrentUser] = useState<User | null>(null); // 当前登录用户
  const [currentView, setCurrentView] = useState('pets'); // 当前路由/视图
  const [allPets, setAllPets] = useState<Pet[]>([]); // 所有宠物数据
  const [posts, setPosts] = useState<Post[]>([]); // 社区帖子数据

  // 初始化：从 localStorage 加载保存的数据
  useEffect(() => {
    const session = localStorage.getItem('app_current_user');
    if (session) setCurrentUser(JSON.parse(session));

    const savedPets = localStorage.getItem('app_pets');
    if (savedPets) setAllPets(JSON.parse(savedPets));

    const savedPosts = localStorage.getItem('app_posts');
    if (savedPosts) setPosts(JSON.parse(savedPosts));
  }, []);

  // 持久化：当数据发生变化时，保存到本地存储
  useEffect(() => {
    localStorage.setItem('app_pets', JSON.stringify(allPets));
  }, [allPets]);

  useEffect(() => {
    localStorage.setItem('app_posts', JSON.stringify(posts));
  }, [posts]);

  // 用户操作处理器
  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('app_current_user', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('app_current_user');
    setCurrentView('pets');
  };

  // 宠物管理逻辑：过滤出属于当前用户的宠物
  const userPets = allPets.filter(p => p.ownerId === currentUser?.id);

  const handleAddPet = (pet: Pet) => {
    if (!currentUser) return;
    const newPet = { ...pet, ownerId: currentUser.id };
    setAllPets([...allPets, newPet]);
  };

  const handleUpdatePet = (updatedPet: Pet) => {
    setAllPets(allPets.map(p => p.id === updatedPet.id ? updatedPet : p));
  };

  const handleDeletePet = (id: string) => {
    setAllPets(allPets.filter(p => p.id !== id));
  };

  // 社区交互逻辑
  const handleAddPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Date.now().toString(),
      userId: currentUser.id,
      username: currentUser.username,
      userAvatar: currentUser.avatar,
      content,
      likes: [],
      comments: [],
      timestamp: new Date().toISOString()
    };
    setPosts([newPost, ...posts]);
  };

  const handleLikePost = (postId: string) => {
    if (!currentUser) return;
    setPosts(posts.map(post => {
      if (post.id === postId) {
        const isLiked = post.likes.includes(currentUser.id);
        const newLikes = isLiked 
          ? post.likes.filter(id => id !== currentUser.id)
          : [...post.likes, currentUser.id];
        return { ...post, likes: newLikes };
      }
      return post;
    }));
  };

  const handleAddComment = (postId: string, content: string) => {
    if (!currentUser) return;
    setPosts(posts.map(post => {
      if (post.id === postId) {
        const newComment: Comment = {
          id: Date.now().toString(),
          userId: currentUser.id,
          username: currentUser.username,
          userAvatar: currentUser.avatar,
          content,
          timestamp: new Date().toISOString()
        };
        return { ...post, comments: [...post.comments, newComment] };
      }
      return post;
    }));
  };

  // 如果未登录，只渲染登录界面
  if (!currentUser) {
    return <Auth onLogin={handleLogin} />;
  }

  // 根据当前 currentView 切换视图
  const renderView = () => {
    switch (currentView) {
      case 'pets':
        return (
          <PetManager 
            currentUser={currentUser}
            pets={userPets} 
            onAddPet={handleAddPet}
            onUpdatePet={handleUpdatePet}
            onDeletePet={handleDeletePet}
            onLogout={handleLogout}
          />
        );
      case 'community':
        return (
          <Community 
            currentUser={currentUser}
            posts={posts}
            onAddPost={handleAddPost}
            onLikePost={handleLikePost}
            onAddComment={handleAddComment}
          />
        );
      case 'guide':
        return <CareGuide />;
      case 'food':
        return <FoodChecker />;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <main className="w-full mx-auto">
        {renderView()}
      </main>
      {/* 底部导航栏 */}
      <Navigation currentView={currentView} setView={setCurrentView} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Pet, PetType, DailyLog, MedicalRecord, DewormingRecord, WeightRecord, User } from '../types';
import { PetForm } from '../components/PetForm';
import { Plus, ChevronRight, Activity, Droplets, Utensils, Syringe, Stethoscope, ArrowLeft, Trash2, Scale, Calendar, AlarmClock, Edit3, Save, LogOut } from 'lucide-react';

interface PetManagerProps {
  currentUser: User;
  pets: Pet[];
  onAddPet: (pet: Pet) => void;
  onUpdatePet: (pet: Pet) => void;
  onDeletePet: (id: string) => void;
  onLogout: () => void;
}

/**
 * 宠物管理核心视图
 * 提供宠物列表展示、宠物详情、以及四个维度的健康打卡（日常、体重、病历、驱虫）
 */
export const PetManager: React.FC<PetManagerProps> = ({ currentUser, pets, onAddPet, onUpdatePet, onDeletePet, onLogout }) => {
  // 视图控制状态
  const [showAddModal, setShowAddModal] = useState(false); // 控制添加宠物的弹窗
  const [selectedPetId, setSelectedPetId] = useState<string | null>(null); // 当前正在查看的宠物 ID
  const [activeTab, setActiveTab] = useState<'daily' | 'weight' | 'medical' | 'deworm'>('daily'); // 详情页的选项卡

  // 表单输入状态
  const [logFood, setLogFood] = useState('');
  const [logWater, setLogWater] = useState('');
  const [medTitle, setMedTitle] = useState('');
  const [medDesc, setMedDesc] = useState('');
  const [wormName, setWormName] = useState('');
  const [wormDate, setWormDate] = useState('');
  const [newWeight, setNewWeight] = useState('');
  const [weightDate, setWeightDate] = useState(new Date().toISOString().split('T')[0]);
  const [memoText, setMemoText] = useState('');
  const [isEditingMemo, setIsEditingMemo] = useState(false);
  const [checkupDate, setCheckupDate] = useState('');
  const [isEditingCheckup, setIsEditingCheckup] = useState(false);
  const [reminderDewormDate, setReminderDewormDate] = useState('');
  const [isEditingDeworm, setIsEditingDeworm] = useState(false);

  const selectedPet = pets.find(p => p.id === selectedPetId);

  // 当切换宠物时，同步该宠物的基本信息到本地状态，以便编辑
  React.useEffect(() => {
    if (selectedPet) {
        setMemoText(selectedPet.memo || '');
        setCheckupDate(selectedPet.nextCheckupDate || '');
        const calculatedNextDeworm = selectedPet.nextDewormDate || 
            (selectedPet.dewormingRecords.length > 0 ? selectedPet.dewormingRecords[0].nextDueDate : '');
        setReminderDewormDate(calculatedNextDeworm);
    }
  }, [selectedPetId, selectedPet]);

  /**
   * 计算宠物年龄（显示为 X岁X个月 或 X天）
   */
  const calculateAge = (birthDateString?: string) => {
    if (!birthDateString) return '年龄未知';
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let years = today.getFullYear() - birthDate.getFullYear();
    let months = today.getMonth() - birthDate.getMonth();

    if (months < 0) {
      years--;
      months += 12;
    }

    if (years === 0 && months === 0) {
        const diffTime = Math.abs(today.getTime() - birthDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        return `${diffDays}天`;
    }

    if (years === 0) return `${months}个月`;
    return `${years}岁${months}个月`;
  };

  /**
   * 计算倒计时天数
   */
  const calculateDaysLeft = (targetDate?: string) => {
      if (!targetDate) return null;
      const today = new Date();
      today.setHours(0,0,0,0);
      const target = new Date(targetDate);
      target.setHours(0,0,0,0);

      const diffTime = target.getTime() - today.getTime();
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // --- 数据保存处理器 ---

  const saveMemo = () => {
      if (!selectedPet) return;
      onUpdatePet({ ...selectedPet, memo: memoText });
      setIsEditingMemo(false);
  };

  const addDailyLog = () => {
    if (!selectedPet) return;
    const newLog: DailyLog = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      foodAmount: Number(logFood) || 0,
      waterAmount: Number(logWater) || 0
    };
    onUpdatePet({ ...selectedPet, dailyLogs: [newLog, ...selectedPet.dailyLogs] });
    setLogFood(''); setLogWater('');
  };

  const addWeightRecord = () => {
    if (!selectedPet || !newWeight) return;
    const newRecord: WeightRecord = {
        id: Date.now().toString(),
        date: weightDate,
        weight: parseFloat(newWeight)
    };
    const updatedRecords = [newRecord, ...(selectedPet.weightRecords || [])].sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
    onUpdatePet({ ...selectedPet, weightRecords: updatedRecords, weight: updatedRecords[0].weight });
    setNewWeight('');
  };

  // --- 渲染逻辑 ---

  // 如果没有选择宠物，渲染“宠物列表”
  if (!selectedPetId) {
    return (
      <div className="pb-24 pt-6 px-4 max-w-lg mx-auto">
        {/* 用户头部信息 */}
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center space-x-3">
             <img src={currentUser.avatar} className="w-10 h-10 rounded-full border-2 border-white shadow-sm" />
             <div>
                <h1 className="text-xl font-bold text-gray-800">你好, {currentUser.username}</h1>
                <p className="text-xs text-gray-500">今天也要好好照顾它们哦</p>
             </div>
          </div>
          <div className="flex space-x-2">
             <button onClick={onLogout} className="bg-white text-gray-600 p-2 rounded-full border"><LogOut size={20} /></button>
             <button onClick={() => setShowAddModal(true)} className="bg-indigo-600 text-white p-2 rounded-full shadow-lg"><Plus size={24} /></button>
          </div>
        </div>

        {/* 宠物列表卡片 */}
        <div className="space-y-4">
          {pets.map(pet => (
            <div key={pet.id} onClick={() => setSelectedPetId(pet.id)} className="bg-white p-4 rounded-2xl shadow-sm border flex items-center space-x-4 cursor-pointer">
              <img src={pet.avatarUrl} className="w-16 h-16 rounded-full object-cover" />
              <div className="flex-1">
                <h3 className="text-lg font-bold">{pet.name}</h3>
                <p className="text-sm text-gray-500">{pet.breed || pet.type} · {calculateAge(pet.birthDate)}</p>
              </div>
              <ChevronRight className="text-gray-300" />
            </div>
          ))}
        </div>
        {showAddModal && <PetForm onSave={(p) => { onAddPet(p); setShowAddModal(false); }} onCancel={() => setShowAddModal(false)} />}
      </div>
    );
  }

  // 如果已选择宠物，渲染该宠物的“详情主页”
  return (
    <div className="pb-24 bg-gray-50 min-h-screen">
      {/* 宠物详情页头部和主要交互模块... (省略重复的 UI 逻辑代码以保持简明) */}
      <div className="p-4 flex items-center justify-between bg-white border-b">
        <button onClick={() => setSelectedPetId(null)}><ArrowLeft size={24}/></button>
        <span className="font-bold">{selectedPet.name} 的主页</span>
        <button onClick={() => onDeletePet(selectedPet.id)} className="text-red-400"><Trash2 size={20}/></button>
      </div>
      {/* 剩余 UI 组件：日常记录、体重曲线等 */}
      <div className="p-4 text-center text-gray-400 text-sm">
        这里是宠物健康档案，包含了日常饮食、医疗和驱虫的所有历史。
      </div>
    </div>
  );
};
